function mmrRank(queryVec, docVecs, k=5, lambda=0.7){
  const selected = [];
  const remaining = docVecs.map((v,i)=>({i,v}));
  while(selected.length < Math.min(k, remaining.length)){
    let best = null, bestScore = -Infinity;
    for(const cand of remaining){
      const relevance = cosine(queryVec, cand.v);
      const diversity = selected.length === 0 ? 0 : Math.max(...selected.map(s=>cosine(s.v, cand.v)));
      const score = lambda*relevance - (1-lambda)*diversity;
      if(score > bestScore){ bestScore = score; best = cand; }
    }
    selected.push(best);
    remaining.splice(remaining.findIndex(x=>x.i===best.i),1);
  }
  return selected;
}
